export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  draft?: boolean;
  layout?: string;
  [key: string]: unknown;
}

export interface Page {
  frontmatter: Frontmatter;
  content: string;
  html: string;
  slug: string;
  sourcePath: string;
}

export interface SiteConfig {
  sourceDir: string;
  templateDir: string;
  outputDir: string;
  siteTitle: string;
  siteUrl: string;
  port: number;
  serve: boolean;
  watch: boolean;
}

export interface TagData {
  tag: string;
  pages: Page[];
}

export interface TemplateContext {
  page?: Page;
  pages?: Page[];
  tags?: TagData[];
  site: { title: string; url: string };
  [key: string]: unknown;
}

import fs from "node:fs";
import path from "node:path";
import matter from "gray-matter";
import { Frontmatter, Page } from "./types";

export function parseFrontmatter(filePath: string): { frontmatter: Frontmatter; content: string } {
  const raw = fs.readFileSync(filePath, "utf-8");
  const { data, content } = matter(raw);
  return {
    frontmatter: data as Frontmatter,
    content: content.trim(),
  };
}

export function slugFromPath(filePath: string, sourceDir: string): string {
  const rel = path.relative(sourceDir, filePath);
  const ext = path.extname(rel);
  let slug = rel.slice(0, -ext.length);
  if (slug.endsWith("/index") || slug === "index") {
    slug = path.dirname(slug) || ".";
  }
  if (slug === ".") slug = "";
  return slug;
}

export function isValidPage(fm: Frontmatter): boolean {
  return !!fm.title && !fm.draft;
}

export async function collectPages(sourceDir: string): Promise<Page[]> {
  const pages: Page[] = [];

  function walk(dir: string) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(fullPath);
      } else if (entry.isFile() && (entry.name.endsWith(".md") || entry.name.endsWith(".mdx"))) {
        const { frontmatter, content } = parseFrontmatter(fullPath);
        const slug = slugFromPath(fullPath, sourceDir);
        pages.push({
          frontmatter,
          content,
          html: "",
          slug,
          sourcePath: fullPath,
        });
      }
    }
  }

  walk(sourceDir);
  return pages;
}

import { Marked } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";

const marked = new Marked(
  markedHighlight({
    langPrefix: "hljs language-",
    highlight(code: string, lang: string) {
      if (lang && hljs.getLanguage(lang)) {
        return hljs.highlight(code, { language: lang }).value;
      }
      return hljs.highlightAuto(code).value;
    },
  })
);

export function markdownToHtml(markdown: string): string {
  const result = marked.parse(markdown);
  if (typeof result === "string") return result;
  return "";
}

export { marked };

import fs from "node:fs";
import path from "node:path";
import Handlebars from "handlebars";
import { TemplateContext, SiteConfig } from "./types";

export function createTemplateEngine(templateDir: string, _config: SiteConfig): HandlebarsTemplateEngine {
  return new HandlebarsTemplateEngine(templateDir);
}

export class HandlebarsTemplateEngine {
  private templates = new Map<string, Handlebars.TemplateDelegate>();
  private templateDir: string;
  private layoutDir: string;
  private partialDir: string;

  constructor(templateDir: string) {
    this.templateDir = templateDir;
    this.layoutDir = path.join(templateDir, "layouts");
    this.partialDir = path.join(templateDir, "partials");
    this.loadPartials();
    this.loadLayouts();
  }

  private loadPartials() {
    if (!fs.existsSync(this.partialDir)) return;
    const files = fs.readdirSync(this.partialDir);
    for (const file of files) {
      if (file.endsWith(".hbs") || file.endsWith(".handlebars")) {
        const name = path.basename(file, path.extname(file));
        const source = fs.readFileSync(path.join(this.partialDir, file), "utf-8");
        Handlebars.registerPartial(name, source);
      }
    }
  }

  private loadLayouts() {
    if (!fs.existsSync(this.layoutDir)) return;
    const files = fs.readdirSync(this.layoutDir);
    for (const file of files) {
      if (file.endsWith(".hbs") || file.endsWith(".handlebars")) {
        const name = path.basename(file, path.extname(file));
        const source = fs.readFileSync(path.join(this.layoutDir, file), "utf-8");
        this.templates.set(`layout:${name}`, Handlebars.compile(source));
      }
    }
  }

  private loadTemplate(name: string): Handlebars.TemplateDelegate {
    const cached = this.templates.get(name);
    if (cached) return cached;

    const filePath = path.join(this.templateDir, `${name}.hbs`);
    if (!fs.existsSync(filePath)) {
      const altPath = path.join(this.templateDir, `${name}.handlebars`);
      if (!fs.existsSync(altPath)) {
        throw new Error(`Template not found: ${name}`);
      }
      const source = fs.readFileSync(altPath, "utf-8");
      const compiled = Handlebars.compile(source);
      this.templates.set(name, compiled);
      return compiled;
    }
    const source = fs.readFileSync(filePath, "utf-8");
    const compiled = Handlebars.compile(source);
    this.templates.set(name, compiled);
    return compiled;
  }

  render(templateName: string, context: TemplateContext): string {
    const contentTemplate = this.loadTemplate(templateName);
    const contentHtml = contentTemplate(context);

    const layoutName = context.page?.frontmatter?.layout ?? "default";
    const layoutKey = `layout:${layoutName}`;
    const layoutTemplate = this.templates.get(layoutKey);

    if (layoutTemplate) {
      const layoutContext = { ...context, body: contentHtml };
      return layoutTemplate(layoutContext);
    }

    return contentHtml;
  }

  renderString(template: string, context: TemplateContext): string {
    const compiled = Handlebars.compile(template);
    return compiled(context);
  }

  clearCache() {
    this.templates.clear();
    this.loadLayouts();
  }
}

import { Page, TagData } from "./types";

export function buildTagData(pages: Page[]): TagData[] {
  const tagMap = new Map<string, Page[]>();

  for (const page of pages) {
    const tags = page.frontmatter.tags ?? [];
    for (const tag of tags) {
      const normalized = tag.toLowerCase().trim();
      if (!tagMap.has(normalized)) {
        tagMap.set(normalized, []);
      }
      tagMap.get(normalized)!.push(page);
    }
  }

  const result: TagData[] = [];
  for (const [tag, taggedPages] of tagMap) {
    taggedPages.sort((a, b) => {
      const da = a.frontmatter.date ?? "";
      const db = b.frontmatter.date ?? "";
      return db.localeCompare(da);
    });
    result.push({ tag, pages: taggedPages });
  }

  result.sort((a, b) => a.tag.localeCompare(b.tag));
  return result;
}

import { Page, SiteConfig } from "./types";

export function generateRss(pages: Page[], config: SiteConfig): string {
  const published = pages
    .filter((p) => !p.frontmatter.draft && p.frontmatter.date)
    .sort((a, b) => {
      const da = a.frontmatter.date ?? "";
      const db = b.frontmatter.date ?? "";
      return db.localeCompare(da);
    });

  const items = published
    .map((page) => {
      const title = escapeXml(page.frontmatter.title ?? page.slug);
      const link = `${config.siteUrl}/${page.slug}`;
      const date = page.frontmatter.date
        ? new Date(page.frontmatter.date).toUTCString()
        : new Date().toUTCString();
      const description = escapeXml(page.content.slice(0, 300));

      return `    <item>
      <title>${title}</title>
      <link>${link}</link>
      <guid isPermaLink="true">${link}</guid>
      <pubDate>${date}</pubDate>
      <description>${description}</description>
    </item>`;
    })
    .join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(config.siteTitle)}</title>
    <link>${config.siteUrl}</link>
    <description>${escapeXml(config.siteTitle)}</description>
    <atom:link href="${config.siteUrl}/rss.xml" rel="self" type="application/rss+xml"/>
${items}
  </channel>
</rss>
`;
}

function escapeXml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

import fs from "node:fs";
import path from "node:path";
import { markdownToHtml } from "./markdown";
import { HandlebarsTemplateEngine } from "./templates";
import { isValidPage, collectPages } from "./frontmatter";
import { buildTagData } from "./tags";
import { generateRss } from "./rss";
import { Page, SiteConfig, TemplateContext, TagData } from "./types";

const RELOAD_SCRIPT = `
<script>
(function() {
  var ws = new WebSocket('ws://' + location.host + '/__livereload');
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') location.reload();
  };
  ws.onclose = function() {
    setTimeout(function() {
      window.location.reload();
    }, 2000);
  };
})();
</script>`;

export async function build(config: SiteConfig, injectReload = false): Promise<void> {
  const engine = new HandlebarsTemplateEngine(config.templateDir);

  fs.mkdirSync(config.outputDir, { recursive: true });

  const allPages = await collectPages(config.sourceDir);
  const pages = allPages.filter((p) => isValidPage(p.frontmatter));

  for (const page of pages) {
    page.html = markdownToHtml(page.content);
  }

  const sortedPages = [...pages].sort((a, b) => {
    const da = a.frontmatter.date ?? "";
    const db = b.frontmatter.date ?? "";
    return db.localeCompare(da);
  });

  const tags = buildTagData(pages);

  const siteContext = { title: config.siteTitle, url: config.siteUrl };

  for (const page of pages) {
    const context: TemplateContext = {
      page,
      pages: sortedPages,
      tags,
      site: siteContext,
    };
    let html = engine.render("post", context);
    if (injectReload) {
      html = html.replace("</body>", `${RELOAD_SCRIPT}</body>`);
    }
    const outDir = path.join(config.outputDir, page.slug);
    fs.mkdirSync(outDir, { recursive: true });
    fs.writeFileSync(path.join(outDir, "index.html"), html);
  }

  if (fs.existsSync(path.join(config.templateDir, "index.hbs")) || fs.existsSync(path.join(config.templateDir, "index.handlebars"))) {
    const indexContext: TemplateContext = {
      pages: sortedPages,
      tags,
      site: siteContext,
    };
    let indexHtml = engine.render("index", indexContext);
    if (injectReload) {
      indexHtml = indexHtml.replace("</body>", `${RELOAD_SCRIPT}</body>`);
    }
    fs.writeFileSync(path.join(config.outputDir, "index.html"), indexHtml);
  }

  if (fs.existsSync(path.join(config.templateDir, "tag.hbs")) || fs.existsSync(path.join(config.templateDir, "tag.handlebars"))) {
    const tagsDir = path.join(config.outputDir, "tags");
    fs.mkdirSync(tagsDir, { recursive: true });

    for (const tagData of tags) {
      const tagContext: TemplateContext = {
        tag: tagData.tag,
        pages: tagData.pages,
        tags,
        site: siteContext,
      } as TemplateContext;
      let tagHtml = engine.render("tag", tagContext);
      if (injectReload) {
        tagHtml = tagHtml.replace("</body>", `${RELOAD_SCRIPT}</body>`);
      }
      fs.writeFileSync(path.join(tagsDir, `${tagData.tag}.html`), tagHtml);
    }
  }

  const rssContent = generateRss(pages, config);
  fs.writeFileSync(path.join(config.outputDir, "rss.xml"), rssContent);

  copyStaticAssets(config.templateDir, config.outputDir);
}

function copyStaticAssets(templateDir: string, outputDir: string) {
  const staticDir = path.join(templateDir, "static");
  if (!fs.existsSync(staticDir)) return;
  copyRecursive(staticDir, outputDir);
}

function copyRecursive(src: string, dest: string) {
  const entries = fs.readdirSync(src, { withFileTypes: true });
  for (const entry of entries) {
    const srcPath = path.join(src, entry.name);
    const destPath = path.join(dest, entry.name);
    if (entry.isDirectory()) {
      fs.mkdirSync(destPath, { recursive: true });
      copyRecursive(srcPath, destPath);
    } else {
      fs.mkdirSync(path.dirname(destPath), { recursive: true });
      fs.copyFileSync(srcPath, destPath);
    }
  }
}

import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import { WebSocketServer, WebSocket } from "ws";
import chokidar from "chokidar";
import { SiteConfig } from "./types";
import { build } from "./build";

export function startDevServer(config: SiteConfig): void {
  const server = http.createServer((req, res) => {
    const url = req.url ?? "/";
    const filePath = url === "/"
      ? path.join(config.outputDir, "index.html")
      : path.join(config.outputDir, url);

    const ext = path.extname(filePath).toLowerCase();
    const mimeTypes: Record<string, string> = {
      ".html": "text/html",
      ".css": "text/css",
      ".js": "application/javascript",
      ".json": "application/json",
      ".png": "image/png",
      ".jpg": "image/jpeg",
      ".svg": "image/svg+xml",
      ".xml": "application/xml",
      ".ico": "image/x-icon",
    };
    const contentType = mimeTypes[ext] ?? "application/octet-stream";

    try {
      const content = fs.readFileSync(filePath);
      res.writeHead(200, { "Content-Type": contentType });
      res.end(content);
    } catch {
      if (!url.includes(".")) {
        try {
          const indexPath = path.join(filePath, "index.html");
          const content = fs.readFileSync(indexPath);
          res.writeHead(200, { "Content-Type": "text/html" });
          res.end(content);
        } catch {
          res.writeHead(404);
          res.end("Not found");
        }
      } else {
        res.writeHead(404);
        res.end("Not found");
      }
    }
  });

  const wss = new WebSocketServer({ server });

  wss.on("connection", (ws: WebSocket) => {
    ws.on("error", () => {});
  });

  function sendReload() {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send("reload");
      }
    }
  }

  let building = false;
  let pendingRebuild = false;

  async function doRebuild() {
    if (building) {
      pendingRebuild = true;
      return;
    }
    building = true;
    pendingRebuild = false;
    try {
      await build(config, true);
      console.log("[statico] Rebuilt at", new Date().toLocaleTimeString());
      sendReload();
    } catch (err) {
      console.error("[statico] Build error:", err);
    } finally {
      building = false;
      if (pendingRebuild) {
        doRebuild();
      }
    }
  }

  const watcher = chokidar.watch([config.sourceDir, config.templateDir], {
    ignoreInitial: true,
    ignorePermissionErrors: true,
  });

  watcher.on("all", (_event: string, _filePath: string) => {
    doRebuild();
  });

  server.listen(config.port, () => {
    console.log(`[statico] Dev server running at http://localhost:${config.port}`);
    console.log(`[statico] Watching ${config.sourceDir} and ${config.templateDir}`);
  });

  process.on("SIGINT", () => {
    watcher.close();
    wss.close();
    server.close();
    process.exit(0);
  });
}

import { SiteConfig } from "./types";

export function parseArgs(args: string[]): SiteConfig {
  const config: SiteConfig = {
    sourceDir: "./content",
    templateDir: "./templates",
    outputDir: "./dist",
    siteTitle: "My Static Site",
    siteUrl: "http://localhost:3000",
    port: 3000,
    serve: false,
    watch: false,
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    const next = args[i + 1];

    switch (arg) {
      case "-s":
      case "--source":
        if (next && !next.startsWith("-")) {
          config.sourceDir = next;
          i++;
        }
        break;
      case "-t":
      case "--templates":
        if (next && !next.startsWith("-")) {
          config.templateDir = next;
          i++;
        }
        break;
      case "-o":
      case "--output":
        if (next && !next.startsWith("-")) {
          config.outputDir = next;
          i++;
        }
        break;
      case "-p":
      case "--port":
        if (next && !next.startsWith("-")) {
          config.port = parseInt(next, 10);
          i++;
        }
        break;
      case "--title":
        if (next && !next.startsWith("-")) {
          config.siteTitle = next;
          i++;
        }
        break;
      case "--url":
        if (next && !next.startsWith("-")) {
          config.siteUrl = next;
          i++;
        }
        break;
      case "-S":
      case "--serve":
        config.serve = true;
        break;
      case "-w":
      case "--watch":
        config.watch = true;
        break;
    }
  }

  return config;
}

export function printHelp(): string {
  return `statico - Static Site Generator

Usage: statico [options]

Options:
  -s, --source <dir>     Source directory of Markdown files (default: ./content)
  -t, --templates <dir>  Template directory of Handlebars files (default: ./templates)
  -o, --output <dir>     Output directory for generated HTML (default: ./dist)
  -p, --port <number>    Dev server port (default: 3000)
  --title <string>       Site title (default: "My Static Site")
  --url <string>         Site base URL for RSS (default: "http://localhost:3000")
  -S, --serve            Start dev server with live reload
  -w, --watch            Watch for changes and rebuild
  -h, --help             Show this help message
`;
}

#!/usr/bin/env node
import { parseArgs, printHelp } from "./cli";
import { build } from "./build";
import { startDevServer } from "./server";

async function main() {
  const args = process.argv.slice(2);

  if (args.includes("-h") || args.includes("--help")) {
    console.log(printHelp());
    process.exit(0);
  }

  const config = parseArgs(args);

  if (config.serve) {
    await build(config, true);
    startDevServer(config);
  } else if (config.watch) {
    await build(config);
    console.log("[statico] Build complete. Watching for changes...");

    const chokidar = await import("chokidar");
    const watcher = chokidar.watch([config.sourceDir, config.templateDir], {
      ignoreInitial: true,
    });

    watcher.on("all", async () => {
      try {
        await build(config);
        console.log("[statico] Rebuilt at", new Date().toLocaleTimeString());
      } catch (err) {
        console.error("[statico] Build error:", err);
      }
    });

    process.on("SIGINT", () => {
      watcher.close();
      process.exit(0);
    });
  } else {
    await build(config);
    console.log("[statico] Build complete.");
  }
}

main().catch((err) => {
  console.error("[statico] Error:", err);
  process.exit(1);
});

import { describe, it, expect } from "vitest";
import { parseFrontmatter, slugFromPath, isValidPage, collectPages } from "../src/frontmatter";
import path from "node:path";

const fixtures = path.resolve(__dirname, "../test-fixtures/content");

